sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_RecordAppendValue(strTable,strSysId,strField,strValue,bGhost,vExpected)
	{
		function TestCase_RecordAppendValue_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected == false)
			{
				return (vExpected == vResult);	
			}
			if (IsString(vExpected) == true)
			{
				return (RecordGetValue(strTable,strSysId,strField) == vExpected);
			}
			return false;
		}
		
		test.TestCase(
			'Function RecordAppendValue()',
			RecordAppendValue,
			{
				'strTable': strTable,
				'strSysId': strSysId,
				'strField': strField,
				'strValue': strValue,
				'bGhost': bGhost
			},
			vExpected,
			TestCase_RecordAppendValue_CheckResult);
	}
		
	TestCase_RecordAppendValue(null,null,null,null,null,false);

	var testdata = new x_snc_devtools.TestDataAPI('ATF.DEVTOOLS');
	var strItemSysId = testdata.CreateTestItem('test1');

	TestCase_RecordAppendValue('x_snc_devtools_test',strItemSysId,'value','Hello',false,'Hello');
	TestCase_RecordAppendValue('x_snc_devtools_test',strItemSysId,'value',' World',false,'Hello World');

	TestCase_RecordAppendValue('x_snc_devtools_test',strItemSysId,'value','\nAnd hello',true,'Hello World\nAnd hello');
	TestCase_RecordAppendValue('x_snc_devtools_test',strItemSysId,'value',' Universe!',true,'Hello World\nAnd hello Universe!');

	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
